-- Create tables\nCREATE TABLE departments (\n    id INT AUTO_INCREMENT PRIMARY KEY,\n    name VARCHAR(255) NOT NULL\n);\n\nCREATE TABLE employees (\n    id INT AUTO_INCREMENT PRIMARY KEY,\n    name VARCHAR(255) NOT NULL,\n    department_id INT,\n    hire_date DATE NOT NULL,\n    salary DECIMAL(10,2) NOT NULL,\n    FOREIGN KEY (department_id) REFERENCES departments(id)\n);\n\n-- Insert initial data\nINSERT INTO departments (name) VALUES ('HR'), ('Engineering'), ('Sales');\n\nINSERT INTO employees (name, department_id, hire_date, salary) VALUES  \n('Alice Johnson', 1, '2025-05-01', 70000.00),\n('Bob Smith', 2, '2023-08-15', 80000.00),\n('Charlie Brown', 3, '2024-03-10', 60000.00);